import java.io.*;
import java.util.Base64;
import javax.servlet.http.*;
import javax.servlet.annotation.WebServlet;
import org.apache.commons.collections4.Transformer;
import org.apache.commons.collections4.functors.*;
import org.apache.commons.collections4.map.LazyMap;
import org.apache.commons.collections4.keyvalue.TiedMapEntry;

/**
 * CI/CD Pipeline Plugin - Build Artifact Cache Handler
 * Accepts serialized BuildCacheEntry objects from trusted build agents
 * to populate the shared artifact cache for downstream pipeline stages.
 */
@WebServlet("/api/v2/cache/artifact")
public class ArtifactCacheServlet extends HttpServlet {

    private static final String CACHE_DIR = "/var/lib/pipeline/cache";
    private static final long MAX_PAYLOAD_SIZE = 10 * 1024 * 1024; // 10MB

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {

        String contentType = req.getContentType();
        if (contentType == null || !contentType.contains("application/x-java-serialized-object")) {
            resp.sendError(415, "Unsupported media type");
            return;
        }

        // Validate agent token header
        String agentToken = req.getHeader("X-Pipeline-Agent-Token");
        if (agentToken == null || agentToken.isEmpty()) {
            resp.sendError(401, "Missing agent token");
            return;
        }

        // Size check
        if (req.getContentLengthLong() > MAX_PAYLOAD_SIZE) {
            resp.sendError(413, "Payload too large");
            return;
        }

        try {
            // Deserialize the cache entry from the build agent
            ObjectInputStream ois = new ObjectInputStream(req.getInputStream());
            Object cacheEntry = ois.readObject();
            ois.close();

            if (cacheEntry instanceof BuildCacheEntry) {
                BuildCacheEntry entry = (BuildCacheEntry) cacheEntry;
                persistCacheEntry(entry);
                resp.setStatus(201);
                resp.getWriter().write("{\"status\":\"cached\",\"key\":\"" + entry.getKey() + "\"}");
            } else {
                resp.sendError(400, "Invalid cache entry type");
            }
        } catch (ClassNotFoundException e) {
            resp.sendError(400, "Unknown class in payload");
        } catch (IOException e) {
            resp.sendError(500, "Cache write failed: " + e.getMessage());
        }
    }

    private void persistCacheEntry(BuildCacheEntry entry) throws IOException {
        File cacheFile = new File(CACHE_DIR, entry.getKey() + ".dat");
        try (FileOutputStream fos = new FileOutputStream(cacheFile);
             ObjectOutputStream oos = new ObjectOutputStream(fos)) {
            oos.writeObject(entry);
        }
    }
}

class BuildCacheEntry implements Serializable {
    private static final long serialVersionUID = 1L;
    private String key;
    private byte[] data;
    private long timestamp;
    private String checksum;

    public BuildCacheEntry(String key, byte[] data) {
        this.key = key;
        this.data = data;
        this.timestamp = System.currentTimeMillis();
    }

    public String getKey() { return key; }
    public byte[] getData() { return data; }
    public long getTimestamp() { return timestamp; }
    public String getChecksum() { return checksum; }
    public void setChecksum(String checksum) { this.checksum = checksum; }
}
